#ifndef BVN_KERNELS_H
#define BVN_KERNELS_H
#define BVN_KERNEL_RELU "; bvn_relu — out[i] = max(0, x[i])\n; args: S16=xbase S17=outbase S18=count S19=step(4) S20=one(1)\n.kernel relu\n    MOV S21, S16\n    MOV S22, S17\n    MOV S23, S18\n    ADDi S24, S0, 0\nrloop:\n    LOAD S1, S21, 0\n    MAX S2, S1, S24\n    STORE S22, S2, 0\n    IADD S21, S21, S19\n    IADD S22, S22, S19\n    ISUB S23, S23, S20\n    CMP P0, S23, S0\n    BR_COND@P0 rdone\n    BR rloop\nrdone:\n    EXIT\n.end"
#define BVN_KERNEL_AFFINE "; bvn_affine — out[i] = x[i]*scale + bias\n; args: S16=xbase S17=outbase S18=scale S19=bias S20=count S21=step(4) S22=one(1)\n.kernel affine\n    MOV S23, S16\n    MOV S24, S17\n    MOV S25, S20\naloop:\n    LOAD S1, S23, 0\n    MUL S2, S1, S18\n    ADD S2, S2, S19\n    STORE S24, S2, 0\n    IADD S23, S23, S21\n    IADD S24, S24, S21\n    ISUB S25, S25, S22\n    CMP P0, S25, S0\n    BR_COND@P0 adone\n    BR aloop\nadone:\n    EXIT\n.end"
#define BVN_KERNEL_SOFTMAX "; bvn_softmax — out[i] = exp(x[i]-max) / sum(exp(x[j]-max))\n; Stable softmax: subtract the max before exponentiating.\n; args: S16=xbase S17=outbase S18=count S19=step(4) S20=one(1) S21=log2e\n.kernel softmax\n    MOV S22, S16\n    MOV S23, S17\n    MOV S24, S18\n    LOAD S25, S22, 0\n    MOV S26, S16\n    MOV S27, S18\nsmaxloop:\n    LOAD S1, S26, 0\n    MAX S25, S1, S25\n    IADD S26, S26, S19\n    ISUB S27, S27, S20\n    CMP P0, S27, S0\n    BR_COND@P0 smaxdone\n    BR smaxloop\nsmaxdone:\n    ADDi S26, S0, 0\n    MOV S22, S16\n    MOV S27, S18\nssumloop:\n    LOAD S1, S22, 0\n    SUB S2, S1, S25\n    MUL S2, S2, S21\n    EXP2 S3, S2\n    ADD S26, S26, S3\n    STORE S23, S3, 0\n    IADD S22, S22, S19\n    IADD S23, S23, S19\n    ISUB S27, S27, S20\n    CMP P0, S27, S0\n    BR_COND@P0 ssumdone\n    BR ssumloop\nssumdone:\n    RCP S21, S26\n    MOV S23, S17\n    MOV S27, S18\nsdivloop:\n    LOAD S1, S23, 0\n    MUL S2, S1, S21\n    STORE S23, S2, 0\n    IADD S23, S23, S19\n    ISUB S27, S27, S20\n    CMP P0, S27, S0\n    BR_COND@P0 sdivdone\n    BR sdivloop\nsdivdone:\n    EXIT\n.end"
#define BVN_KERNEL_SIGMUL "; bvn_sigmul — out[i] = x[i] / (1 + exp2(x[i]*c))\n; Swish family: c = -1.702*log2(e) gives GELU (sigmoid approx);\n; c = -log2(e) gives SiLU.  exp(-z) is computed as exp2(-z*log2e).\n; args: S16=xbase S17=outbase S18=count S19=step(4) S20=one(1) S21=c\n.kernel sigmul\n    MOV S22, S16\n    MOV S23, S17\n    MOV S24, S18\ngloop:\n    LOAD S1, S22, 0\n    MUL S2, S1, S21\n    EXP2 S2, S2\n    ADDi S3, S2, 1\n    RCP S3, S3\n    MUL S3, S3, S1\n    STORE S23, S3, 0\n    IADD S22, S22, S19\n    IADD S23, S23, S19\n    ISUB S24, S24, S20\n    CMP P0, S24, S0\n    BR_COND@P0 gdone\n    BR gloop\ngdone:\n    EXIT\n.end"
#endif
